import React, { useState, useEffect } from 'react';

function ProductsList() {
  const [products, setProducts] = useState([]); 
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchProducts = async () => {
      try {
        const token = localStorage.getItem('token'); // si tu API requiere JWT
        const res = await fetch('http://localhost/api/productes', {
          headers: {
            'Content-Type': 'application/json',
            'Authorization': token ? `Bearer ${token}` : ''
          }
        });
        if (!res.ok) throw new Error('Error al obtenir productes');

        const data = await res.json();
        console.log('Products API response:', data); // para depurar

        // Ajuste: data ya es un array
        setProducts(data || []);
        setLoading(false);
      } catch (err) {
        console.error('Error fetching products:', err);
        setError(err.message);
        setLoading(false);
      }
    };

    fetchProducts();
  }, []);

  if (loading) return <p>Carregant productes...</p>;
  if (error) return <p>Error: {error}</p>;
  if (products.length === 0) return <p>No hi ha productes disponibles.</p>;

  return (
    <div className="row">
      {products.map(product => (
        <div key={product.id} className="col-md-4 mb-3">
          <div className="card h-100">
            <div className="card-body">
              <h5 className="card-title">{product.nom}</h5>
              <p className="card-text">{product.descripcio}</p>
              <p className="card-text"><strong>Referència:</strong> {product.referencia}</p>
              <p className="card-text"><strong>Quantitat:</strong> {product.quantitat}</p>
            </div>
          </div>
        </div>
      ))}
    </div>
  );
}

export default ProductsList;
